async function handleListSessions(
  ws: WebSocket,
  sessionStore: SessionStore | undefined,
  options: SessionListOptions
): Promise<void> {
  const {userId} = ws as WebSocket & {userId: string | number};
  const {limit, before} = options;
  const query: SessionListOptions = {...(limit !== undefined ? {limit} : {}), ...(before ? {before} : {})};
  try {
    const summaries = (await sessionStore?.listFor?.(userId, query)) ?? [];
    sendJson(ws, {
      type: 'session_list',
      sessions: summaries.map(summary => ({
        sessionId: summary.sessionId,
        createdAt: summary.createdAt.toISOString(),
        updatedAt: summary.updatedAt.toISOString(),
        entryCount: summary.entryCount,
      })),
    });
  } catch (error) {
    log.error('ws', 'session list failed', {userId, error: error instanceof Error ? error.message : String(error)});
